/**
 * Contract between the brain-model pipeline output and the app:
 * - src/lib/content/brain-model.json (generated by tools/brain-pipeline/optimize.mjs)
 * - public/models/*.glb (the files it points at)
 * - tools/brain-pipeline/structures.json (the source-mesh → part mapping)
 */
import { readFileSync, statSync } from "node:fs";
import { join } from "node:path";

import brainModel from "../brain-model.json";

const ROOT = join(__dirname, "../../../..");
const MAX_MODEL_BYTES = 3 * 1024 * 1024;

interface StructureSpec {
  parts: Record<string, { group: string; midline?: boolean }>;
  source: { sha256: string; license: string };
}

const spec = JSON.parse(
  readFileSync(join(ROOT, "tools/brain-pipeline/structures.json"), "utf8"),
) as StructureSpec;

/** Node names from the JSON chunk of a binary glTF. */
function glbNodeNames(file: string): string[] {
  const buffer = readFileSync(join(ROOT, "public", file));
  const jsonLength = buffer.readUInt32LE(12);
  const gltf = JSON.parse(buffer.subarray(20, 20 + jsonLength).toString("utf8")) as {
    nodes: { name?: string; mesh?: number }[];
  };
  return gltf.nodes
    .filter((node) => node.mesh !== undefined)
    .map((node) => node.name ?? "")
    .sort();
}

const nodeNames = Object.keys(brainModel.nodes).sort();

/** Parts the explorer's first release relies on (docs/planning/04, levels 1–2). */
const REQUIRED_PARTS = [
  "prefrontal",
  "motor_frontal",
  "parietal",
  "temporal",
  "occipital",
  "insula",
  "anterior_cingulate",
  "limbic_posterior",
  "cerebellum",
  "midbrain",
  "midbrain_tegmentum",
  "pons",
  "medulla",
  "corpus_callosum",
  "thalamus",
  "hypothalamus",
  "caudate",
  "putamen",
  "globus_pallidus",
  "nucleus_accumbens",
  "substantia_nigra",
  "amygdala",
  "hippocampus",
];

describe("brain model manifest", () => {
  it("points at a published model of the recorded size", () => {
    const { file, bytes } = brainModel.model;
    expect(statSync(join(ROOT, "public", file)).size).toBe(bytes);
  });

  it("keeps the compressed model within the 3 MB budget", () => {
    expect(brainModel.model.bytes).toBeLessThanOrEqual(MAX_MODEL_BYTES);
  });

  it("publishes a model that contains exactly the manifest's nodes", () => {
    expect(glbNodeNames(brainModel.model.file)).toEqual(nodeNames);
  });

  it("names every node <side>_<part> with a part from structures.json", () => {
    for (const [name, node] of Object.entries(brainModel.nodes)) {
      expect(name).toBe(`${node.side}_${node.part}`);
      expect(spec.parts[node.part]?.group).toBe(node.group);
    }
  });

  it("exports midline parts once and bilateral parts on both sides", () => {
    for (const [part, info] of Object.entries(spec.parts)) {
      const sides = nodeNames.filter((n) => n.endsWith(`_${part}`)).map((n) => n.split("_")[0]);
      expect(sides.sort()).toEqual(info.midline ? ["mid"] : ["lh", "rh"]);
    }
  });

  it("contains every part the explorer needs", () => {
    const parts = new Set(Object.values(brainModel.nodes).map((node) => node.part));
    expect(REQUIRED_PARTS.filter((part) => !parts.has(part))).toEqual([]);
  });

  it("records a pinned, CC BY 4.0 source", () => {
    expect(brainModel.source.license).toBe("CC BY 4.0");
    expect(brainModel.source.sha256).toBe(spec.source.sha256);
  });
});
